using CellBridge.Storage.Abstractions;

namespace CellBridge.AspNetCore;

internal readonly record struct OfficeRealTimeRoomKey(Guid ResourceId, long LifecycleGeneration);

// Incarnation is generated by the accepting host and is never reused. A host
// restart changes HostId, so stale process cleanup cannot remove live members.
internal sealed record OfficeRealTimeBackplaneMember(OfficeRealTimeRoomKey Room,
    string ConnectionId, Guid Incarnation, Guid HostId, OfficeRealTimeTicket Ticket)
{
    public string ClientKey { get; init; } = "";
    public string SubjectIndexKey { get; init; } = "";
    public string SubjectIndexMember { get; init; } = "";
    public long LeaseExpiresUnixMilliseconds { get; init; }
}

internal sealed record OfficeRealTimeBackplanePresence(string ClientKey, Guid Incarnation, string Payload);

internal sealed record OfficeRealTimeBackplaneSnapshot(string Epoch, long Watermark,
    long RedisTimeMilliseconds, IReadOnlyList<OfficeRealTimeBackplaneMember> Members,
    IReadOnlyList<OfficeRealTimeBackplanePresence> Presence);

internal enum OfficeRealTimeBackplaneStatus { Ok, Busy, Reset, Denied, Missing }

internal sealed record OfficeRealTimeBackplaneConnectResult(OfficeRealTimeBackplaneStatus Status,
    OfficeRealTimeBackplaneSnapshot? Snapshot);

internal sealed record OfficeRealTimeBackplaneSnapshotResult(OfficeRealTimeBackplaneStatus Status,
    OfficeRealTimeBackplaneSnapshot? Snapshot);

internal sealed record OfficeRealTimeBackplaneEvent(long Sequence, string EventId,
    string Epoch, DateTimeOffset CreatedUtc, long RedisTimeMilliseconds, string Kind, string ClientKey, OfficeRealTimeBackplaneMember Sender,
    string Method, string PayloadJson);

internal sealed record OfficeRealTimeBackplaneEventsResult(OfficeRealTimeBackplaneStatus Status,
    string? Epoch, long Watermark, long RedisTimeMilliseconds,
    IReadOnlyList<OfficeRealTimeBackplaneEvent> Events, bool HasGap, bool NeedsCleanup);

internal sealed record OfficeRealTimeBackplaneMutationResult(OfficeRealTimeBackplaneStatus Status,
    string? Epoch, long Sequence, long RedisTimeMilliseconds);

internal sealed record OfficeRealTimeBackplaneHeartbeatResult(OfficeRealTimeBackplaneStatus Status,
    IReadOnlySet<Guid> CurrentIncarnations, long RedisTimeMilliseconds);

internal sealed record OfficeRealTimeBackplaneRemoveResult(OfficeRealTimeBackplaneStatus Status,
    string? Epoch, long? DepartureSequence, long RedisTimeMilliseconds);

internal sealed record OfficeRealTimeBackplaneMembersResult(OfficeRealTimeBackplaneStatus Status,
    string? Epoch, IReadOnlyList<OfficeRealTimeBackplaneMember> Members, long RedisTimeMilliseconds);

/// <summary>Transient cross-process RTC coordination. Implementations must not retry an
/// ambiguous mutation because callers cannot determine whether a notification was published.</summary>
internal interface IOfficeRealTimeBackplane : IAsyncDisposable
{
    long Generation { get; }
    bool IsHealthy { get; }
    Task<OfficeRealTimeBackplaneConnectResult> ConnectAsync(OfficeRealTimeBackplaneMember member,
        CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneSnapshotResult> ReadSnapshotAsync(OfficeRealTimeRoomKey room,
        CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneEventsResult> ReadEventsAsync(OfficeRealTimeRoomKey room,
        string epoch, long afterSequence, int maxEvents, int maxBytes, CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneMembersResult> ObserveMembersAsync(OfficeRealTimeRoomKey room,
        CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneMutationResult> MutateAsync(OfficeRealTimeBackplaneMember member,
        string epoch, string eventId, string kind, string clientKey, string method, string payloadJson,
        CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneHeartbeatResult> HeartbeatAsync(
        IReadOnlyList<OfficeRealTimeBackplaneMember> members, CancellationToken cancellationToken);

    Task<OfficeRealTimeBackplaneRemoveResult> RemoveAsync(OfficeRealTimeBackplaneMember member,
        string? presenceClientKey, string eventId, CancellationToken cancellationToken);
}

// Pub/Sub only reduces the time until the ordered room log is read. It never
// carries event data or changes membership, sequence, authorization, or health.
internal interface IOfficeRealTimeBackplaneWakeSource
{
    event Action<OfficeRealTimeRoomKey>? RoomChanged;
}
